solution.solution.cpp:
#include <cstddef>
#include <type_traits>

template <typename... Ts>
struct TypeList {};

template <typename List>
struct Length;

template <typename... Ts>
struct Length<TypeList<Ts...>>
{
    static constexpr std::size_t value{ sizeof...(Ts) };
};

template <typename T, typename List>
struct Contains;

template <typename T, typename... Ts>
struct Contains<T, TypeList<Ts...>>
{
    static constexpr bool value{ (std::is_same_v<T, Ts> || ...) };
};

template <typename List>
struct Front;

template <typename First, typename... Rest>
struct Front<TypeList<First, Rest...>>
{
    using type = First;
};

unitTests:
using Numbers = TypeList<int, double, long>;
static_assert(Length<Numbers>::value == 3 && Length<TypeList<>>::value == 0);
static_assert(Contains<double, Numbers>::value && !Contains<char, Numbers>::value && !Contains<int, TypeList<>>::value);
static_assert(std::is_same_v<Front<Numbers>::type, int> && std::is_same_v<Front<TypeList<char>>::type, char>);

TEST("all of it happened at compile time") { CHECK_EQ(Length<Numbers>::value, 3u); CHECK(Contains<long, Numbers>::value); }

